// Zip backups via Windows' built-in tar (bsdtar), plus world management.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { run, tarPath, dirSize, safeJoin, copyDir } = require('./util');

// Folders that are regenerated by the server and just waste backup space.
const EXCLUDES = ['logs', 'cache', 'crash-reports', 'libraries', 'versions', '.fabric', 'session.lock', '*.part'];

function backupDirFor(backupsRoot, serverDir) {
  const hash = crypto.createHash('sha1').update(path.resolve(serverDir).toLowerCase()).digest('hex').slice(0, 8);
  const dir = path.join(backupsRoot, `${path.basename(serverDir)}-${hash}`);
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function listBackups(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir)
    .filter((f) => f.endsWith('.zip'))
    .map((name) => {
      const stat = fs.statSync(path.join(dir, name));
      return { name, size: stat.size, created: stat.mtimeMs, path: path.join(dir, name) };
    })
    .sort((a, b) => b.created - a.created);
}

function timestamp() {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}_${p(d.getHours())}-${p(d.getMinutes())}-${p(d.getSeconds())}`;
}

async function createBackup({ serverDir, dir, label = 'manual', maxBackups = 5, exclude = [] }) {
  if (!fs.existsSync(serverDir)) throw new Error('Server directory does not exist yet');
  const name = `backup-${timestamp()}-${label}.zip`;
  const out = path.join(dir, name);
  const args = ['-a', '-c', '-f', out];
  for (const ex of [...EXCLUDES, ...exclude]) args.push('--exclude', ex);
  args.push('-C', serverDir, '.');

  const res = await run(tarPath(), args, { timeout: 30 * 60 * 1000 });
  // bsdtar exits 1 on warnings (e.g. a file locked by the server) but the archive is still valid.
  if (!fs.existsSync(out) || (res.code !== 0 && res.code !== 1)) {
    fs.rmSync(out, { force: true });
    throw new Error('Backup failed: ' + (res.stderr || `tar exit ${res.code}`).slice(0, 300));
  }

  // Retention: keep the newest N backups.
  const all = listBackups(dir);
  for (const old of all.slice(Math.max(1, maxBackups))) fs.rmSync(old.path, { force: true });

  return { name, size: fs.statSync(out).size };
}

function worldFolders(serverDir) {
  if (!fs.existsSync(serverDir)) return [];
  return fs.readdirSync(serverDir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && fs.existsSync(path.join(serverDir, e.name, 'level.dat')))
    .map((e) => e.name);
}

async function restoreBackup({ serverDir, file }) {
  if (!fs.existsSync(file)) throw new Error('Backup file not found');
  // Remove current worlds first, otherwise newer region files would survive the restore.
  for (const w of worldFolders(serverDir)) {
    fs.rmSync(path.join(serverDir, w), { recursive: true, force: true });
  }
  const res = await run(tarPath(), ['-xf', file, '-C', serverDir], { timeout: 30 * 60 * 1000 });
  if (res.code !== 0) throw new Error('Restore failed: ' + res.stderr.slice(0, 300));
}

function deleteBackup(dir, name) {
  if (name !== path.basename(name)) throw new Error('Invalid backup name');
  fs.rmSync(path.join(dir, name), { force: true });
}

// --- Worlds ---

function listWorlds(serverDir, levelName) {
  const base = levelName || 'world';
  return worldFolders(serverDir).map((name) => {
    const full = path.join(serverDir, name);
    let dimension = 'overworld';
    if (name.endsWith('_nether')) dimension = 'nether';
    if (name.endsWith('_the_end')) dimension = 'end';
    return {
      name,
      dimension,
      size: dirSize(full),
      modified: fs.statSync(path.join(full, 'level.dat')).mtimeMs,
      active: name === base || name === `${base}_nether` || name === `${base}_the_end`,
      primary: name === base,
    };
  }).sort((a, b) => Number(b.active) - Number(a.active) || a.name.localeCompare(b.name));
}

function deleteWorld(serverDir, name) {
  const target = safeJoin(serverDir, name);
  if (target === path.resolve(serverDir)) throw new Error('Invalid world');
  fs.rmSync(target, { recursive: true, force: true });
}

// Regenerating = deleting the active world and its dimensions; the server
// creates fresh ones (with the configured seed) on next start.
function resetWorld(serverDir, levelName) {
  const base = levelName || 'world';
  for (const name of [base, `${base}_nether`, `${base}_the_end`]) {
    const target = path.join(serverDir, name);
    if (fs.existsSync(target)) fs.rmSync(target, { recursive: true, force: true });
  }
}

function importWorld(serverDir, sourceDir) {
  if (!fs.existsSync(path.join(sourceDir, 'level.dat'))) {
    throw new Error('That folder is not a Minecraft world (no level.dat found)');
  }
  let name = path.basename(sourceDir).replace(/[^\w\- ]/g, '_');
  while (fs.existsSync(path.join(serverDir, name))) name += '_imported';
  copyDir(sourceDir, path.join(serverDir, name));
  return name;
}

module.exports = {
  backupDirFor, listBackups, createBackup, restoreBackup, deleteBackup,
  listWorlds, deleteWorld, resetWorld, importWorld,
};
